/**
 * The 10 built-in stadiums, generated by code exactly like the official
 * `w.Fd()` (headless f066733d): same construction order, same expressions
 * (including `Math.tan` for the curved segments, evaluated at build time),
 * same "unset" fields (`bgGoalLine` is never assigned by the grass builder
 * and serializes as NaN; `bgColor` is never assigned by the hockey builder
 * and serializes as 0).
 *
 * Builders: grass `lb` -> buildGrass, hockey `gf` -> buildHockey, goal
 * `Wc` -> addGoal, kick-off barrier `hf` -> addKickOffBarrier, rounded
 * corners `ff` -> addRoundedCorners.
 */
import { applySegmentCurve, prepareStadium } from './geometry.js';
import { Disc, Goal, Plane, Segment, Stadium, Vertex } from './types.js';

const TEAM_RED = 1;
const TEAM_BLUE = 2;
const RED_POST_COLOR = 16764108; // 0xFFCCCC
const BLUE_POST_COLOR = 13421823; // 0xCCCCFF
const GRASS_BG_COLOR = 7441498; // 0x718C5A

/** Default ball (off `w.Vc`). */
export function createDefaultBall(): Disc {
  const d = new Disc();
  d.color = 16777215;
  d.cMask = 63;
  d.cGroup = 193;
  d.radius = 10;
  d.damping = 0.99;
  d.invMass = 1;
  d.bCoef = 0.5;
  return d;
}

/** A stadium with the official constructor's state (unset numeric fields = NaN as on the wire). */
function blankStadium(name: string): Stadium {
  const s = new Stadium();
  s.defaultStadiumId = 255;
  s.name = name;
  s.bgType = 0;
  s.bgWidth = NaN;
  s.bgHeight = NaN;
  s.bgKickOffRadius = NaN;
  s.bgCornerRadius = NaN;
  s.bgGoalLine = NaN;
  s.bgColor = 0; // undefined -> i32 0
  s.width = NaN;
  s.height = NaN;
  s.spawnDistance = NaN;
  s.maxViewWidth = 0;
  s.cameraFollow = 0;
  s.canBeStored = true;
  s.fullKickOffReset = false;
  return s;
}

function vertex(x: number, y: number): Vertex {
  const v = new Vertex();
  v.x = x;
  v.y = y;
  return v;
}

function plane(nx: number, ny: number, dist: number): Plane {
  const p = new Plane();
  p.normalX = nx;
  p.normalY = ny;
  p.dist = dist;
  return p;
}

/** The four camera-bounding planes, bCoef 0 (shared by both builders). */
function addCameraPlanes(s: Stadium, width: number, height: number): void {
  let p = plane(0, 1, -height);
  p.bCoef = 0;
  s.planes.push(p);
  p = plane(0, -1, -height);
  p.bCoef = 0;
  s.planes.push(p);
  p = plane(1, 0, -width);
  p.bCoef = 0;
  s.planes.push(p);
  p = plane(-1, 0, -width);
  p.bCoef = 0;
  s.planes.push(p);
}

/** Ball-only plane (cMask = ball). */
function ballPlane(nx: number, ny: number, dist: number): Plane {
  const p = plane(nx, ny, dist);
  p.cMask = 1;
  return p;
}

/** off `w.Wc(x, dir, halfGoal, postColor, team, cMask = 1)`; cGroup is always 32. */
function addGoal(s: Stadium, x: number, dir: number, half: number, postColor: number, team: number, cMask = 1): void {
  const cGroup = 32;
  const top = vertex(x + 8 * dir, -half);
  const bottom = vertex(x + 8 * dir, half);
  const backTop = vertex(top.x + 22 * dir, top.y + 22);
  const backBottom = vertex(bottom.x + 22 * dir, bottom.y - 22);
  const s0 = new Segment(top, backTop);
  applySegmentCurve(s0, 90 * dir);
  const s1 = new Segment(backBottom, backTop);
  const s2 = new Segment(backBottom, bottom);
  applySegmentCurve(s2, 90 * dir);

  const v0 = s.vertexes.length;
  s.vertexes.push(top, bottom, backTop, backBottom);
  for (let i = v0; i < s.vertexes.length; i++) {
    const v = s.vertexes[i]!;
    v.cMask = cMask;
    v.cGroup = cGroup;
    v.bCoef = 0.1;
  }
  const g0 = s.segments.length;
  s.segments.push(s0, s1, s2);
  for (let i = g0; i < s.segments.length; i++) {
    const g = s.segments[i]!;
    g.cMask = cMask;
    g.cGroup = cGroup;
    g.bCoef = 0.1;
  }

  let post = new Disc();
  post.x = x;
  post.y = -half;
  post.invMass = 0;
  post.radius = 8;
  post.color = postColor;
  s.discs.push(post);
  post = new Disc();
  post.x = x;
  post.y = half;
  post.invMass = 0;
  post.radius = 8;
  post.color = postColor;
  s.discs.push(post);

  const goal = new Goal();
  goal.p0x = x;
  goal.p0y = -half;
  goal.p1x = x;
  goal.p1y = half;
  goal.team = team;
  s.goals.push(goal);
}

function barrierVertex(y: number): Vertex {
  const v = vertex(0, y);
  v.bCoef = 0.1;
  v.cGroup = 24;
  v.cMask = 6;
  return v;
}

/** off `w.hf(kickOffRadius, height)`: centre line + kick-off half circles. */
function addKickOffBarrier(s: Stadium, radius: number, height: number): void {
  const top = barrierVertex(-height);
  const koTop = barrierVertex(-radius);
  const koBottom = barrierVertex(radius);
  const bottom = barrierVertex(height);

  const upper = new Segment(top, koTop);
  upper.cGroup = 24;
  upper.cMask = 6;
  upper.vis = false;
  upper.bCoef = 0.1;
  const lower = new Segment(koBottom, bottom);
  lower.cGroup = 24;
  lower.cMask = 6;
  lower.vis = false;
  lower.bCoef = 0.1;
  const redArc = new Segment(koTop, koBottom);
  redArc.cGroup = 8;
  redArc.cMask = 6;
  redArc.vis = false;
  applySegmentCurve(redArc, 180);
  redArc.bCoef = 0.1;
  const blueArc = new Segment(koBottom, koTop);
  blueArc.cGroup = 16;
  blueArc.cMask = 6;
  blueArc.vis = false;
  applySegmentCurve(blueArc, 180);
  blueArc.bCoef = 0.1;

  s.vertexes.push(top, koTop, koBottom, bottom);
  s.segments.push(upper, lower, redArc, blueArc);
}

function cornerVertex(x: number, y: number): Vertex {
  const v = vertex(x, y);
  v.cMask = 0;
  return v;
}

function cornerSegment(a: Vertex, b: Vertex, curve: number): Segment {
  const g = new Segment(a, b);
  g.cMask = 1;
  g.vis = false;
  g.bCoef = 1;
  applySegmentCurve(g, curve);
  return g;
}

/** off `w.ff(bgWidth, bgHeight, cornerRadius)`: ball-only rounded corners. */
function addRoundedCorners(s: Stadium, w: number, h: number, r: number): void {
  if (0 >= r) return;
  const a = cornerVertex(-w + r, -h);
  const b = cornerVertex(-w, -h + r);
  const c = cornerVertex(-w + r, h);
  const d = cornerVertex(-w, h - r);
  const e = cornerVertex(w - r, h);
  const f = cornerVertex(w, h - r);
  const g = cornerVertex(w - r, -h);
  const k = cornerVertex(w, -h + r);
  const s0 = cornerSegment(a, b, -90);
  const s1 = cornerSegment(c, d, 90);
  const s2 = cornerSegment(e, f, -90);
  const s3 = cornerSegment(g, k, 90);
  s.vertexes.push(a, b, c, d, e, f, g, k);
  s.segments.push(s0, s1, s2, s3);
}

function ballOnlyLine(a: Vertex, b: Vertex): Segment {
  const g = new Segment(a, b);
  g.cMask = 1;
  g.vis = false;
  return g;
}

/** off `w.lb(name, width, height, bgWidth, bgHeight, goalHalf, kickOffRadius, cornerRadius = 0)` (grass). */
function buildGrass(
  name: string, width: number, height: number, bgW: number, bgH: number,
  goalHalf: number, kickOffRadius: number, cornerRadius = 0,
): Stadium {
  const s = blankStadium(name);
  s.discs.push(createDefaultBall());
  s.width = width;
  s.height = height;
  s.bgType = 1;
  s.bgColor = GRASS_BG_COLOR;
  s.bgWidth = bgW;
  s.bgHeight = bgH;
  s.bgKickOffRadius = kickOffRadius;
  s.bgCornerRadius = cornerRadius;
  s.spawnDistance = 0.75 * bgW;
  if (400 < s.spawnDistance) s.spawnDistance = 400;
  addCameraPlanes(s, width, height);
  addGoal(s, bgW, 1, goalHalf, BLUE_POST_COLOR, TEAM_BLUE);
  addGoal(s, -bgW, -1, goalHalf, RED_POST_COLOR, TEAM_RED);
  addKickOffBarrier(s, kickOffRadius, height);
  s.planes.push(ballPlane(0, 1, -bgH));
  s.planes.push(ballPlane(0, -1, -bgH));

  const a = cornerVertex(-bgW, -bgH);
  const b = cornerVertex(bgW, -bgH);
  const c = cornerVertex(bgW, -goalHalf);
  const d = cornerVertex(bgW, goalHalf);
  const e = cornerVertex(bgW, bgH);
  const f = cornerVertex(-bgW, bgH);
  const g = cornerVertex(-bgW, goalHalf);
  const k = cornerVertex(-bgW, -goalHalf);
  const s0 = ballOnlyLine(b, c);
  const s1 = ballOnlyLine(d, e);
  const s2 = ballOnlyLine(f, g);
  const s3 = ballOnlyLine(k, a);
  s.vertexes.push(a, b, c, d, e, f, g, k);
  s.segments.push(s0, s1, s2, s3);
  addRoundedCorners(s, bgW, bgH, cornerRadius);
  prepareStadium(s);
  return s;
}

/** off `w.gf(name, width, height, bgWidth, bgHeight, goalHalf, goalLine, cornerRadius)` (hockey). */
function buildHockey(
  name: string, width: number, height: number, bgW: number, bgH: number,
  goalHalf: number, goalLine: number, cornerRadius: number,
): Stadium {
  const s = blankStadium(name);
  s.discs.push(createDefaultBall());
  s.width = width;
  s.height = height;
  s.bgType = 2;
  s.bgWidth = bgW;
  s.bgHeight = bgH;
  s.bgKickOffRadius = 75;
  s.bgCornerRadius = cornerRadius;
  s.bgGoalLine = goalLine;
  s.spawnDistance = 0.75 * (bgW - goalLine);
  if (400 < s.spawnDistance) s.spawnDistance = 400;
  addCameraPlanes(s, width, height);
  addGoal(s, bgW - goalLine, 1, goalHalf, BLUE_POST_COLOR, TEAM_BLUE, 63);
  addGoal(s, -bgW + goalLine, -1, goalHalf, RED_POST_COLOR, TEAM_RED, 63);
  addKickOffBarrier(s, 75, height);
  s.planes.push(ballPlane(0, 1, -bgH));
  s.planes.push(ballPlane(0, -1, -bgH));
  s.planes.push(ballPlane(1, 0, -bgW));
  s.planes.push(ballPlane(-1, 0, -bgW));
  addRoundedCorners(s, bgW, bgH, cornerRadius);
  prepareStadium(s);
  return s;
}

let cache: Stadium[] | null = null;

/**
 * Built-in stadiums, index = defaultStadiumId (off `w.Fd()`):
 * 0 Classic, 1 Easy, 2 Small, 3 Big, 4 Rounded, 5 Hockey, 6 Big Hockey,
 * 7 Big Easy, 8 Big Rounded, 9 Huge. Built once and SHARED (like the
 * official cache): never mutate them; use {@link buildDefaultStadium} for a
 * private copy.
 */
export function defaultStadiums(): readonly Stadium[] {
  if (cache === null) {
    const list: Stadium[] = [];
    for (let i = 0; i < DEFAULT_STADIUM_COUNT; i++) list.push(buildDefaultStadium(i));
    cache = list;
  }
  return cache;
}

export const DEFAULT_STADIUM_COUNT = 10;

/** Builds a fresh (unshared) copy of built-in stadium `id` (0..9), with `defaultStadiumId = id`. */
export function buildDefaultStadium(id: number): Stadium {
  let s: Stadium;
  switch (id) {
    case 0: s = buildGrass('Classic', 420, 200, 370, 170, 64, 75); break;
    case 1: s = buildGrass('Easy', 420, 200, 370, 170, 90, 75); break;
    case 2: s = buildGrass('Small', 420, 200, 320, 130, 55, 70); break;
    case 3: s = buildGrass('Big', 600, 270, 550, 240, 80, 80); break;
    case 4: s = buildGrass('Rounded', 420, 200, 370, 170, 64, 75, 75); break;
    case 5: s = buildHockey('Hockey', 420, 204, 398, 182, 68, 120, 100); break;
    case 6: s = buildHockey('Big Hockey', 600, 270, 550, 240, 90, 160, 150); break;
    case 7: s = buildGrass('Big Easy', 600, 270, 550, 240, 95, 80); break;
    case 8: s = buildGrass('Big Rounded', 600, 270, 550, 240, 80, 75, 100); break;
    case 9: s = buildGrass('Huge', 750, 350, 700, 320, 100, 80); break;
    default: throw new RangeError(`no default stadium #${id}`);
  }
  s.defaultStadiumId = id;
  return s;
}
